<template><CoopTaskSheet :show="show" :title="lead?.id ? '选择交付门店' : '找交付门店'" :subtitle="lead?.region_text || '按客户所在地区查找，不使用 ERP 的地区编号'" :busy="busy" full @close="$emit('close')"><view class="coop-store-picker"><view v-if="!lead?.id" class="coop-filter-region"><CoopRegionFields v-model="region" /><u-button size="small" text="按地区查找" :disabled="!region.district_id" @click="load" /></view><view class="coop-scope-tabs"><text v-for="option in scopes" :key="option.value" :class="{ active: scope === option.value }" @tap="changeScope(option.value)">{{ option.label }}</text></view><u-search v-model="keyword" placeholder="搜索门店或联系人" :show-action="true" action-text="查询" @search="load" @custom="load" @clear="load" /><view class="coop-store-caption">{{ reason || '同一地区内，靠谱认证优先，其次为等级和型号匹配' }}</view><CoopState v-if="loading || error" :loading="loading" :error="error" @retry="load" /><template v-else><CoopStoreCard v-for="store in rows" :key="store.id" :store="store" :selectable="!!lead?.id" :selected="Number(selected?.id) === Number(store.id)" @select="choose" /><CoopState v-if="!rows.length" title="暂时没有匹配门店" hint="可调整关键词，或查看同城、全省的门店" icon="home" /></template></view><template #footer><template v-if="lead?.id"><view class="coop-footer-note">仅交付给选中的一家门店，不会群发</view><u-button type="primary" shape="circle" :text="selected ? `确认交付给${selected.name}` : '请选择交付门店'" :loading="busy" :disabled="!selected || busy || loading" @click="$emit('assign', selected)" /></template><u-button v-else shape="circle" text="返回" @click="$emit('close')" /></template></CoopTaskSheet></template>
<script setup lang="ts">
import { onBeforeUnmount, ref, watch } from 'vue'
import { cooperationStores, coopError, type CoopRow } from '../../api/cooperation'
import CoopTaskSheet from './CoopTaskSheet.vue'
import CoopRegionFields from './CoopRegionFields.vue'
import CoopState from './CoopState.vue'
import CoopStoreCard from './CoopStoreCard.vue'
const props = defineProps<{ show: boolean; lead?: CoopRow; profile?: CoopRow; busy?: boolean }>()
const emit = defineEmits<{ (event: 'close'): void; (event: 'assign', row: CoopRow): void }>()
const keyword = ref(''), scope = ref('auto'), selected = ref<CoopRow | null>(null), rows = ref<CoopRow[]>([]), reason = ref(''), loading = ref(false), error = ref(''), region = ref<CoopRow>({ province_id: 0, city_id: 0, district_id: 0 })
const scopes = [{ value: 'auto', label: '优先本区县' }, { value: 'district', label: '本区县' }, { value: 'city', label: '全市' }, { value: 'province', label: '全省' }]
let sequence = 0
async function load() { const token = ++sequence; selected.value = null; loading.value = true; error.value = ''; try { const response: any = await cooperationStores({ ...region.value, scope: scope.value, keyword: keyword.value.trim() }, Number(props.lead?.id || 0)); if (token !== sequence || !props.show) return; const payload = response.data || {}; rows.value = Array.isArray(payload) ? payload : payload.data || []; reason.value = payload.reason || '' } catch (cause) { if (token === sequence && props.show) error.value = coopError(cause, '门店读取失败') } finally { if (token === sequence) loading.value = false } }
function choose(store: CoopRow) { if (props.lead?.id && !props.busy) selected.value = store; else if (store.name) uni.showModal({ title: store.name, content: `${store.region_text || ''}\n${store.is_reliable ? '靠谱认证不代表现货或赔付担保。' : ''}库存仅供匹配参考，实际交付请向门店核对。`, showCancel: false }) }
function changeScope(value: string) { if (loading.value || props.busy || scope.value === value) return; scope.value = value; void load() }
watch(() => props.show, show => { if (show) { keyword.value = ''; scope.value = 'auto'; selected.value = null; region.value = { province_id: props.lead?.province_id || props.profile?.province_id || 0, city_id: props.lead?.city_id || props.profile?.city_id || 0, district_id: props.lead?.district_id || props.profile?.district_id || 0 }; void load() } else { sequence++; loading.value = false } })
onBeforeUnmount(() => { sequence++ })
defineExpose({ load })
</script>
<style scoped lang="scss">.coop-store-picker { padding: 20rpx 24rpx; }.coop-scope-tabs { display: flex; gap: 30rpx; align-items: center; margin: 4rpx 4rpx 24rpx; font-size: 24rpx; color: #8b939e; }.coop-scope-tabs>text { min-height: 70rpx; display: flex; align-items: center; }.coop-scope-tabs .active { color: var(--primary-color, #d93833); font-weight: 600; }.coop-store-caption { font-size: 22rpx; color: #8d96a1; line-height: 1.8; margin: 22rpx 4rpx; }.coop-filter-region { padding: 10rpx 4rpx 20rpx; }.coop-filter-region :deep(.u-button) { margin-top: 16rpx; }.coop-footer-note { text-align: center; font-size: 23rpx; color: #8d96a0; margin-bottom: 15rpx; }</style>
